contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function taking arbitrary addresses and value
    function run(address to, uint256 value) public payable {
        require(to != address(0)); // _transfer requires non-zero recipient, so skip degenerate input

        // Observe pre-state via public getters
        address ownerBefore = c.owner();
        uint256 totalBefore = c.totalSupply();
        uint256 balSenderBefore = c.balanceOf(address(this));
        uint256 balToBefore = c.balanceOf(to);

        // attempt transfer from this contract (msg.sender for C calls will be this contract)
        bool reverted;
        try c.transfer(to, value) returns (bool ok) {
            // transfer returned (should be true by implementation) and did not revert
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe post-state
        uint256 totalAfter = c.totalSupply();
        uint256 balSenderAfter = c.balanceOf(address(this));
        uint256 balToAfter = c.balanceOf(to);

        // Rule: totalSupply never changes as a result of transfer, and if transfer succeeded,
        // then sender decreased by exactly the amount gained by receiver; if it reverted,
        // balances and totalSupply must be unchanged for the two accounts observed.
        assert(
            // totalSupply invariant always holds
            totalBefore == totalAfter
            && (
                // either transfer reverted -> both balances unchanged
                (reverted && balSenderBefore == balSenderAfter && balToBefore == balToAfter)
                ||
                // or transfer succeeded -> conservation between the two accounts
                (!reverted && balSenderAfter + value == balSenderBefore && balToAfter == balToBefore + value)
            )
        );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    address deployer;

    constructor(C _c) {
        c = _c;
        deployer = msg.sender; // record deployer (EOA that created this test)
    }

    // single public function that encodes the property test
    function run(address target, uint256 amt, bool freeze) public payable {
        // Precondition: target can be any address; amt any uint256. No extra require needed.

        // Read initial public state
        address ownerBefore = c.owner();
        uint256 totalBefore = c.totalSupply();
        uint256 balOwnerBefore = c.balanceOf(ownerBefore);
        uint256 balTargetBefore = c.balanceOf(target);
        bool frozenBefore = c.frozenAccount(target);

        // 1) Try calling freezeAccount as this contract (not owner unless owner==address(this))
        bool frozeReverted;
        try c.freezeAccount(target, freeze) {
            frozeReverted = false;
        } catch {
            frozeReverted = true;
        }
        // Read resulting frozen state
        bool frozenAfter = c.frozenAccount(target);

        // 2) Try calling burn as this contract
        bool burnReverted;
        try c.burn(amt) returns (bool ok) {
            burnReverted = false;
        } catch {
            burnReverted = true;
        }
        // Read resulting totals/balances after burn attempt
        uint256 totalAfterBurn = c.totalSupply();
        uint256 balOwnerAfterBurn = c.balanceOf(ownerBefore);

        // 3) Try calling mintToken as this contract
        bool mintReverted;
        try c.mintToken(target, amt) {
            mintReverted = false;
        } catch {
            mintReverted = true;
        }
        uint256 totalAfterMint = c.totalSupply();
        uint256 balTargetAfterMint = c.balanceOf(target);

        // Determine whether this test contract is the owner
        bool isOwner = (address(this) == ownerBefore);

        /* General rule asserted:
           - If caller is owner (isOwner==true): none of the three calls should revert; freezeAccount should set frozenAccount[target]==freeze;
             burn should reduce totalSupply by amt and reduce owner's balance by amt (when owner's balance >= amt); mintToken should increase totalSupply by amt and increase target balance by amt.
           - If caller is not owner: all three calls must revert and thus state must remain as before for frozenAccount, totalSupply and balances (i.e., no observable change from these calls).

           We must express this as a single assert over the observed values and revert flags.
        */

        if (isOwner) {
            // Owner case: expect no reverts
            // For burn there is an internal require balanceOf[owner] >= amt; if owner's balance < amt the burn SHOULD revert.
            // So when owner and balOwnerBefore >= amt: burnReverted must be false and totals/balances updated accordingly.
            // When owner and balOwnerBefore < amt: burnReverted must be true and totals/balances unchanged from before burn.

            bool burn_expected_to_succeed = (balOwnerBefore >= amt);

            assert(
                // freeze must succeed and change frozenAccount to 'freeze'
                (frozeReverted == false) && (frozenAfter == freeze)
                // mint must succeed and increase total and target balance by amt
                && (mintReverted == false)
                && (totalAfterMint == totalBefore + amt)
                && (balTargetAfterMint == balTargetBefore + amt)
                // burn behavior depends on owner's balance
                && (
                    (burn_expected_to_succeed && burnReverted == false && totalAfterBurn == totalBefore - amt && balOwnerAfterBurn == balOwnerBefore - amt)
                    || (!burn_expected_to_succeed && burnReverted == true && totalAfterBurn == totalBefore && balOwnerAfterBurn == balOwnerBefore)
                )
            );
        } else {
            // Non-owner case: all three must revert and none of the public values should have changed from their before-values
            assert(
                frozeReverted == true
                && frozenAfter == frozenBefore
                && burnReverted == true
                && totalAfterBurn == totalBefore
                && balOwnerAfterBurn == balOwnerBefore
                && mintReverted == true
                && totalAfterMint == totalBefore
                && balTargetAfterMint == balTargetBefore
            );
        }
    }

    // allow receiving ETH if needed by other tests
    receive() external payable {}
}

