contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: try transferring from this contract to some recipient
    function run(address to, uint256 value, address other) public payable {
        require(to != address(0)); // transfers to zero address are known to revert in C, avoid trivial always-revert
        require(other != to);
        // observe before-values
        uint256 beforeTotal = c.totalSupply();
        uint256 beforeSender = c.balanceOf(address(this));
        uint256 beforeTo = c.balanceOf(to);
        uint256 beforeOther = c.balanceOf(other);

        bool didRevert;
        try c.transfer(to, value) {
            didRevert = false;
        } catch {
            didRevert = true;
        }

        uint256 afterTotal = c.totalSupply();
        uint256 afterSender = c.balanceOf(address(this));
        uint256 afterTo = c.balanceOf(to);
        uint256 afterOther = c.balanceOf(other);

        // General rule: if the transfer succeeded then totalSupply is unchanged and
        // only sender and recipient balances may have changed with conservation between them;
        // if it reverted then nothing observable (totalSupply and balances) changed.
        assert(
            didRevert
            ? (afterTotal == beforeTotal && afterSender == beforeSender && afterTo == beforeTo && afterOther == beforeOther)
            : (afterTotal == beforeTotal &&
               // sender decreased by exactly amount transferred OR stayed same if underflow prevented success
               (beforeSender - afterSender == afterTo - beforeTo) &&
               // other unrelated address unchanged
               afterOther == beforeOther)
        );
    }

    receive() external payable { }
}
